function buildGoogleApiUrl(modelName, apiKey, apiVersion = 'v1beta') {
  return `https://generativelanguage.googleapis.com/${apiVersion}/models/${modelName}:generateContent?key=${apiKey}`;
}

function buildXaiImageGenerationBody({ modelName, prompt, aspectRatio, count, resolution }) {
  return JSON.stringify({
    model: modelName,
    prompt: prompt.trim(),
    n: count,
    aspect_ratio: aspectRatio,
    resolution,
    response_format: 'b64_json',
  });
}

function buildGeminiImageGenerationConfig({ modelConfig, aspectRatio }) {
  const image = {
    aspectRatio,
  };

  if (modelConfig.imageSize) {
    image.imageSize = modelConfig.imageSize;
    return {
      responseModalities: ['TEXT', 'IMAGE'],
      responseFormat: {
        image,
      },
    };
  }

  return {
    responseModalities: ['TEXT', 'IMAGE'],
    imageConfig: {
      aspectRatio,
    },
  };
}

async function fetchWithTimeout(url, options, timeoutMs = 90000) {
  const controller = new AbortController();
  const timeoutId = window.setTimeout(() => controller.abort(), timeoutMs);

  try {
    return await fetch(url, {
      ...options,
      signal: controller.signal,
    });
  } finally {
    window.clearTimeout(timeoutId);
  }
}

export async function parseDllPicApiError(response) {
  let payload = null;

  try {
    payload = await response.json();
  } catch {
    // Fall through to status text.
  }

  const apiMessage = payload?.error?.message;
  const promptBlockReason = payload?.promptFeedback?.blockReason;
  const finishReason = payload?.candidates?.[0]?.finishReason;

  if (apiMessage) return `API 錯誤 (${response.status}): ${apiMessage}`;
  if (promptBlockReason) return `請求被模型阻擋：${promptBlockReason}`;
  if (finishReason === 'SAFETY') return '請求被安全機制阻擋，請改寫 Prompt 後重試';
  return `API 請求失敗 (${response.status}${response.statusText ? ` ${response.statusText}` : ''})`;
}

export function getDllPicModelConfig(modelKey) {
  if (modelKey === 'grok') return DLL_PIC_MODEL_CONFIG.xaiGrokImagineQuality;
  const modelConfig = DLL_PIC_MODEL_CONFIG[modelKey];
  if (modelConfig?.redirectModelKey) return DLL_PIC_MODEL_CONFIG[modelConfig.redirectModelKey];
  return modelConfig || DLL_PIC_MODEL_CONFIG.google31FlashLiteImage;
}

export function normalizeDllPicModelKey(modelKey, fallback = 'google31FlashLiteImage') {
  if (modelKey === 'openaiImage2') return 'openaiImage26Flare';
  if (modelKey === 'grok') return 'xaiGrokImagineQuality';
  const modelConfig = DLL_PIC_MODEL_CONFIG[modelKey];
  if (modelConfig?.redirectModelKey) return modelConfig.redirectModelKey;
  return modelConfig && (!modelConfig.hidden || [DLL_MOSS_MODEL_KEYS.lora, DLL_ASIAN_MIX_MODEL_KEYS.lora, DLL_ASIAN_MIX_MODEL_KEYS.radiance, DLL_QWEN_MODEL_KEYS.lora, DLL_QWEN_MODEL_KEYS.omni].includes(modelKey)) ? modelKey : fallback;
}

export function getDllPicLoraSelection(modelKey) {
  if (Object.values(DLL_ASIAN_MIX_MODEL_KEYS).includes(modelKey)) {
    const radiance = modelKey === DLL_ASIAN_MIX_MODEL_KEYS.radiance;
    return { modelKey: DLL_ASIAN_MIX_MODEL_KEYS.base, supported: true, enabled: modelKey !== DLL_ASIAN_MIX_MODEL_KEYS.base,
      adjustable: true, strength: (radiance ? COMFY_CONTRACT.models.zImageTurboRadiance : COMFY_CONTRACT.models.zImageTurboAsianMix).loraStrength.default,
      label: radiance ? 'Radiance LoRA' : 'Asian Mix LoKr', strengthLabel: radiance ? 'LoRA 強度' : 'LoKr 強度',
      loraModelKey: radiance ? DLL_ASIAN_MIX_MODEL_KEYS.radiance : DLL_ASIAN_MIX_MODEL_KEYS.lora,
      storageKey: radiance ? DLL_PIC_STORAGE_KEYS.radianceStrength : DLL_PIC_STORAGE_KEYS.asianMixStrength,
      hint: radiance ? '直接使用目前 Prompt。' : '需要時可在提示詞加入 asian woman。' };
  }
  if (Object.values(DLL_QWEN_MODEL_KEYS).includes(modelKey)) {
    const omni = modelKey === DLL_QWEN_MODEL_KEYS.omni;
    return { modelKey: DLL_QWEN_MODEL_KEYS.base, supported: true, enabled: modelKey !== DLL_QWEN_MODEL_KEYS.base,
      adjustable: true, strength: (omni ? COMFY_CONTRACT.models.qwenImage21OmniLora : COMFY_CONTRACT.models.qwenImage21Lora).loraStrength.default,
      label: omni ? 'Omni LoRA' : 'v1.3b LoRA', strengthLabel: 'LoRA 強度',
      loraModelKey: omni ? DLL_QWEN_MODEL_KEYS.omni : DLL_QWEN_MODEL_KEYS.lora,
      storageKey: omni ? DLL_PIC_STORAGE_KEYS.qwenOmniLoraStrength : DLL_PIC_STORAGE_KEYS.qwenLoraStrength,
      hint: '直接使用目前 Prompt。' };
  }
  const supported = Object.values(DLL_MOSS_MODEL_KEYS).includes(modelKey);
  return { modelKey: supported ? DLL_MOSS_MODEL_KEYS.base : modelKey,
    supported, enabled: modelKey === DLL_MOSS_MODEL_KEYS.lora, strength: supported ? 0.7 : null };
}

export function getDllPicLoraModelKey(modelKey, enabled) {
  const selection = getDllPicLoraSelection(modelKey);
  if (!selection.supported) return modelKey;
  if (selection.adjustable) {
    return enabled === true ? selection.loraModelKey : selection.modelKey;
  }
  return enabled === true ? DLL_MOSS_MODEL_KEYS.lora : DLL_MOSS_MODEL_KEYS.base;
}

export function getDllPicLoraSettings(modelKey, strength) {
  const model = getDllPicModelConfig(modelKey);
  return model.loraStrength ? normalizeProviderLoraStrength(model, strength) : {};
}

export function readDllPicLoraStrength(modelKey, readValue) {
  const selection = getDllPicLoraSelection(modelKey);
  if (!selection.adjustable) return selection.strength;
  try {
    const stored = readValue(selection.storageKey);
    const value = stored == null || String(stored).trim() === '' ? undefined : Number(stored);
    return getDllPicLoraSettings(selection.loraModelKey, value).loraStrength;
  } catch {
    return selection.strength;
  }
}

export function isDllPicAspectRatioSupported(modelKey, aspectRatio) {
  const model = getDllPicModelConfig(modelKey);
  if (model.aspectRatios) return model.aspectRatios.includes(aspectRatio);
  if (!DLL_PIC_ASPECT_RATIOS.some((option) => option.value === aspectRatio)) return false;
  if (aspectRatio !== '4:5') return true;
  return model === DLL_PIC_MODEL_CONFIG.google31FlashLiteImage;
}

export function getDllPicSelectableModelEntries({ includeAnalysisOnly = false } = {}) {
  return Object.entries(DLL_PIC_MODEL_CONFIG).filter(([, model]) => (
    !model.hidden && (!includeAnalysisOnly || model.analysisModel)
  ));
}

export function getDllPicApiKeyStorageKeys(modelKey) {
  const modelConfig = getDllPicModelConfig(modelKey);
  return [
    modelConfig.apiKeyStorageKey,
    modelConfig.legacyApiKeyStorageKey,
  ].filter(Boolean);
}

export function getDllPicApiKeyForModel(modelKey, providerApiKeys = {}) {
  const modelConfig = getDllPicModelConfig(modelKey);
  return (providerApiKeys[modelConfig.provider] || '').trim();
}

export function getDllPicResolutionOptions(modelKey) {
  const modelConfig = getDllPicModelConfig(modelKey);
  const allowedValues = modelConfig.resolutionOptions || DEFAULT_DLL_PIC_RESOLUTION_VALUES;
  return DLL_PIC_RESOLUTIONS.filter((option) => allowedValues.includes(option.value))
    .map((option) => ({ ...option, label: modelConfig.resolutionLabels?.[option.value] || option.label }));
}

export function getDllPicResolutionOption(modelKeyOrResolution, resolution) {
  const hasModelKey = resolution !== undefined;
  const modelKey = hasModelKey ? modelKeyOrResolution : null;
  const targetResolution = hasModelKey ? resolution : modelKeyOrResolution;
  const fallbackModelKey = hasModelKey ? modelKey : 'google31FlashLiteImage';
  const modelConfig = getDllPicModelConfig(fallbackModelKey);
  const options = getDllPicResolutionOptions(fallbackModelKey);
  const defaultResolution = modelConfig.defaultResolution || options[0]?.value;
  return options.find((option) => option.value === targetResolution)
    || options.find((option) => option.value === defaultResolution)
    || options[0];
}

export function normalizeDllPicImageCount(count = 1) {
  const parsedCount = Number(count);
  return Number.isFinite(parsedCount) ? Math.max(1, Math.min(2, Math.floor(parsedCount))) : 1;
}

async function notifyDllPicObserver(callback, payload, images) {
  try {
    await callback?.(payload);
  } catch (error) {
    const observerError = error instanceof Error ? error : new Error(String(error));
    observerError.images = [...images];
    throw observerError;
  }
}

async function generateGeminiImages({
  apiKey,
  modelConfig,
  prompt,
  aspectRatio,
  count,
}) {
  const body = JSON.stringify({
    contents: [{
      parts: [{ text: prompt.trim() }],
    }],
    generationConfig: buildGeminiImageGenerationConfig({ modelConfig, aspectRatio }),
  });

  const responses = await Promise.all(Array.from({ length: count }, () => (
    fetchWithTimeout(buildGoogleApiUrl(modelConfig.generationModel, apiKey, modelConfig.apiVersion), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body,
    })
  )));

  const images = [];
  const errors = [];

  for (const response of responses) {
    if (!response.ok) {
      errors.push(await parseDllPicApiError(response));
      continue;
    }

    const data = await response.json();
    const parts = data.candidates?.[0]?.content?.parts || [];
    const imagePart = parts.find((part) => part.inlineData?.mimeType?.startsWith('image/'));
    const textPart = parts.find((part) => part.text);

    if (imagePart) {
      images.push({
        src: `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`,
        mimeType: imagePart.inlineData.mimeType,
      });
    } else if (textPart?.text) {
      errors.push(`模型回應: ${textPart.text}`);
    } else if (data.promptFeedback?.blockReason) {
      errors.push(`請求被模型阻擋：${data.promptFeedback.blockReason}`);
    }
  }

  return { images, errors };
}

async function generateXaiImages({
  apiKey,
  modelConfig,
  prompt,
  aspectRatio = '9:16',
  count = 1,
  resolution = '1k',
}) {
  const response = await fetchWithTimeout('https://api.x.ai/v1/images/generations', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${apiKey}`,
    },
    body: buildXaiImageGenerationBody({
      modelName: modelConfig.generationModel,
      prompt,
      aspectRatio,
      count,
      resolution,
    }),
  });

  if (!response.ok) {
    throw new Error(await parseDllPicApiError(response));
  }

  const data = await response.json();
  const images = (data.data || []).flatMap((image) => {
    if (image.b64_json) {
      return [{
        src: `data:${image.mime_type || 'image/jpeg'};base64,${image.b64_json}`,
        mimeType: image.mime_type || 'image/jpeg',
      }];
    }

    if (image.url) {
      return [{
        src: image.url,
        mimeType: image.mime_type || 'image/jpeg',
      }];
    }

    return [];
  });

  return { images, errors: [] };
}

