export async function generateDllPicImages({
  apiKey,
  modelKey = 'google',
  prompt,
  aspectRatio = '9:16',
  count = 1,
  resolution = '1k',
  magnificGenerate = null,
  bytePlusGenerate = null,
  comfyGenerate = null,
  seed, requestId, loraStrength, thinkingMode, faceSourceId,
  onProgress,
  onImages,
}) {
  const modelConfig = getDllPicModelConfig(modelKey);
  if (!apiKey && !modelConfig.usesServerProxy) throw new Error('請先設定 DLL_PIC Pro API Key');
  if (!prompt?.trim()) throw new Error('請先選擇或輸入 Prompt');
  if (!modelConfig.generationModel) throw new Error(`${modelConfig.label} 目前尚未接入生圖功能`);

  const normalizedResolution = getDllPicResolutionOption(modelKey, resolution).value;
  const normalizedCount = normalizeDllPicImageCount(count);
  if (modelConfig.provider === 'comfyCloud' && !comfyGenerate) throw new Error('Comfy Cloud Firebase Proxy 尚未接入');
  if (modelConfig.provider === 'comfyCloud') {
    if (!modelConfig.resolutionOptions.includes(resolution)) throw new Error(`${modelConfig.label} 不支援 ${resolution} 解析度`);
    const result = await comfyGenerate({
      modelKey: modelConfig.comfyModel, prompt, aspectRatio, count: normalizedCount, resolution,
      ...(modelConfig.comfyModel === 'seedream5Pro' && faceSourceId ? { faceSourceId } : {}),
      ...getDllPicLoraSettings(modelKey, loraStrength),
      ...(modelConfig.comfyModel === 'krea3' ? { thinkingMode: thinkingMode ?? 'fast' } : {}),
      ...(seed !== undefined ? { seed } : {}), ...(requestId ? { requestId } : {}),
    }, { onProgress, onImages });
    if (result.images.length === 0) throw new Error(result.errors[0] || 'API 回應中未包含圖像資料。');
    return result;
  }

  const images = [];
  const errors = [];
  let lastResult;
  for (let sequenceIndex = 1; sequenceIndex <= normalizedCount; sequenceIndex += 1) {
    await notifyDllPicObserver(onProgress, { status: 'running', sequenceIndex, sequenceTotal: normalizedCount, images: [...images] }, images);
    let result;
    try {
      result = modelConfig.provider === 'magnific'
        ? await generateMagnificImages({ magnificGenerate, modelConfig, prompt, aspectRatio, count: 1, resolution: normalizedResolution })
        : modelConfig.provider === 'byteplus'
          ? await generateBytePlusImages({ bytePlusGenerate, modelConfig, prompt, aspectRatio, count: 1, resolution: normalizedResolution })
          : modelConfig.provider === 'xai'
            ? await generateXaiImages({ apiKey, modelConfig, prompt, aspectRatio, count: 1, resolution: normalizedResolution })
            : await generateGeminiImages({ apiKey, modelConfig, prompt, aspectRatio, count: 1 });
      if (result.images.length === 0) throw new Error(result.errors[0] || 'API 回應中未包含圖像資料。');
    } catch (error) {
      if (images.length === 0) throw error;
      const message = typeof error === 'string' ? error : error?.message || error?.details || error?.code || '生成失敗';
      errors.push(`第 ${sequenceIndex} 張生成失敗：${message}`);
      break;
    }
    images.push(...result.images);
    errors.push(...(result.errors || []).map((error) => `第 ${sequenceIndex} 張：${error}`));
    lastResult = result;
    await notifyDllPicObserver(onImages, [...images], images);
    if (normalizedCount === 1) return result;
  }
  return {
    images,
    errors,
    meta: { ...lastResult?.meta, requestedCount: normalizedCount, completedCount: images.length, partial: images.length < normalizedCount },
  };
}

function normalizeJsonText(text = '') {
  const trimmed = text.trim();
  const fencedMatch = trimmed.match(/```(?:json)?\s*([\s\S]*?)```/i);
  return fencedMatch ? fencedMatch[1].trim() : trimmed;
}

function formatStructuredAnalysis(structuredAnalysis) {
  if (!structuredAnalysis || typeof structuredAnalysis !== 'object') return '';

  const fieldLabels = {
    subject: 'Subject',
    style: 'Style',
    composition: 'Composition',
    lighting: 'Lighting',
    color: 'Color',
    mood: 'Mood',
    camera: 'Camera',
    wardrobe: 'Wardrobe',
    keyDetails: 'Key Details',
  };

  return Object.entries(fieldLabels)
    .map(([key, label]) => {
      const value = structuredAnalysis[key];
      return value ? `${label}: ${value}` : null;
    })
    .filter(Boolean)
    .join('\n');
}

export function parseDllPicAnalysisResponse(text = '') {
  const normalizedText = normalizeJsonText(text);

  try {
    const parsed = JSON.parse(normalizedText);
    return {
      shortPrompt: parsed.shortPrompt?.trim() || '',
      detailedPrompt: parsed.detailedPrompt?.trim() || '',
      structuredPrompt: formatStructuredAnalysis(parsed.structuredAnalysis) || parsed.structuredPrompt?.trim() || '',
    };
  } catch {
    return {
      shortPrompt: text.trim(),
      detailedPrompt: text.trim(),
      structuredPrompt: '',
    };
  }
}

export async function analyzeImageToPrompt({
  apiKey,
  modelKey = 'google',
  imageDataUrl,
  instruction = '',
}) {
  const modelConfig = getDllPicModelConfig(modelKey);
  if (!apiKey) throw new Error('請先設定 DLL_PIC Pro API Key');
  if (!imageDataUrl) throw new Error('請先上傳圖片');
  if (!modelConfig.analysisModel) throw new Error(`${modelConfig.label} 目前尚未接入圖片分析功能`);

  const base64Data = imageDataUrl.split(',')[1];
  const mimeType = imageDataUrl.split(';')[0].split(':')[1];
  const extraInstruction = instruction.trim() ? ` Additional instruction: ${instruction.trim()}` : '';
  const analysisInstruction = `Analyze this image and return valid JSON only. Generate three outputs in English for AI image generation:
1. shortPrompt: one concise prompt for quick testing
2. detailedPrompt: one richer production-ready prompt in the current GPT image prompt style
3. structuredAnalysis: an object with keys subject, style, composition, lighting, color, mood, camera, wardrobe, keyDetails

Do not include markdown, code fences, or commentary.${extraInstruction}`;

  const response = await fetchWithTimeout(
    buildGoogleApiUrl(modelConfig.analysisModel, apiKey),
    {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [{
          parts: [
            {
              inlineData: {
                mimeType,
                data: base64Data,
              },
            },
            { text: analysisInstruction },
          ],
        }],
      }),
    }
  );

  if (!response.ok) {
    throw new Error(await parseDllPicApiError(response));
  }

  const data = await response.json();
  const responseText = data.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!responseText) throw new Error('無法解析 API 回應');
  return parseDllPicAnalysisResponse(responseText);
}

